    ["GetTrainerServiceDescription(68)"] = "1: string Calls down a pillar of fire, burning all enemies within the area for 154 to 192 Fire damage and an additional 132 Fire damage over 8 sec. Only one Flamestrike can be active per Mage at a time.",
    ["GetTrainerServiceDescription(69)"] = "1: string Absorbs 284 Frost damage.  Lasts 30 sec.",
    ["GetTrainerServiceDescription(7)"] = "1: string Hurls a fiery ball that causes 26 to 38 Fire damage and an additional 3 Fire damage over 6 sec.",
    ["GetTrainerServiceDescription(70)"] = "1: string Launches a bolt of frost at the enemy, causing 128 to 140  Frost damage and slowing movement speed by 40% for 8 sec.",
    ["GetTrainerServiceDescription(71)"] = "1: string Targets in a cone in front of the caster take 137 to 151  Frost damage and are slowed by 40% for 6 sec. The first 4 targets hit by this cone are slowed by an additional 10% for an additional 3 sec.\r\n",
    ["GetTrainerServiceDescription(72)"] = "1: string Deals 41 to 49 Frost damage to an enemy target. Deals 200% increased damage to Frozen targets.",
    ["GetTrainerServiceDescription(73)"] = "1: string Increases your resistance to all magic by 5 and allows 50% of your mana regeneration to continue while casting.  Only one type of Armor spell can be active on the Mage at any time.  Lasts 30 min.",
    ["GetTrainerServiceDescription(74)"] = "1: string Scorch the enemy for 63 to 75 Fire damage.",
    ["GetTrainerServiceDescription(75)"] = "1: string Launches a projectile of pure Arcane energy at the enemy target, causing 168 to 206 Arcane damage. This spell gains additional Spell Damage equal to 5% of your maximum Mana.",
    ["GetTrainerServiceDescription(76)"] = "1: string A wave of flame radiates outward from the caster, damaging all enemies caught within the blast for 193 to 231 Fire damage, and Dazing them for 50% reduced movement speed for 6 sec.",
    ["GetTrainerServiceDescription(77)"] = "1: string Ice shards pelt the target area doing 496 Frost damage over 8 sec.",
    ["GetTrainerServiceDescription(78)"] = "1: string Dampens magic used against the targeted party member, decreasing damage taken from spells by up to 60 and healing spells by up to 120.  Lasts 10 min.",
    ["GetTrainerServiceDescription(79)"] = "1: string Hurls a fiery ball that causes 162 to 212 Fire damage and an additional 24 Fire damage over 8 sec.",
    ["GetTrainerServiceDescription(8)"] = "1: string Launches Arcane Missiles at the enemy, causing 24 Arcane damage each second for 3 sec.",
    ["GetTrainerServiceDescription(80)"] = "1: string Quickly launch a weak blast of frost at the enemy, causing 43 to 47 Frost damage and slowing movement speed by 40% for 9 sec.",
    ["GetTrainerServiceDescription(81)"] = "1: string Absorbs 300 physical damage, draining mana instead.  Drains 2.0 mana per damage absorbed.  Lasts 1 min.",
    ["GetTrainerServiceDescription(82)"] = "1: string Hurls an immense fiery boulder that causes 216 to 274 Fire damage and an additional 100 Fire damage over 12 sec.",
    ["GetTrainerServiceDescription(83)"] = "1: string Causes an explosion of arcane magic around the caster, causing 129 to 141 Arcane damage to all targets within 10 yards.",
    ["GetTrainerServiceDescription(84)"] = "1: string Conjures a mana jade that can be used to instantly restore 550 to 650 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.",
    ["GetTrainerServiceDescription(85)"] = "1: string Blasts the enemy for 215 to 257 Fire damage.",
    ["GetTrainerServiceDescription(86)"] = "1: string Launches a bolt of frost at the enemy, causing 173 to 189  Frost damage and slowing movement speed by 40% for 8 sec.",
    ["GetTrainerServiceDescription(87)"] = "1: string Blasts the target with energy, dealing 93 to 109 Arcane damage. Each time you cast Arcane Blast, you gain 15% of your Intellect as Spell Damage and the mana cost of Arcane Blast is increased by 175%. Effect stacks up to 4 times and lasts 15 sec from time of initial application.",
    ["GetTrainerServiceDescription(88)"] = "1: string Launches Arcane Missiles at the enemy, causing 95 Arcane damage each second for 5 sec.",
    ["GetTrainerServiceDescription(89)"] = "1: string Conjures 2 bottles of mineral water, providing the mage and his allies with something to drink.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.",
    ["GetTrainerServiceDescription(9)"] = "1: string Launches a bolt of frost at the enemy, causing 27 to 31  Frost damage and slowing movement speed by 40% for 6 sec.",
    ["GetTrainerServiceDescription(90)"] = "1: string Absorbs 463 Fire damage.  Lasts 30 sec.",
    ["GetTrainerServiceDescription(91)"] = "1: string Calls down a pillar of fire, burning all enemies within the area for 220 to 272 Fire damage and an additional 188 Fire damage over 8 sec. Only one Flamestrike can be active per Mage at a time.",
    ["GetTrainerServiceDescription(92)"] = "1: string Blasts enemies near the caster for 50 to 56 Frost damage and freezes them in place for up to 8 sec.  Damage caused may interrupt the effect.",
    ["GetTrainerServiceDescription(93)"] = "1: string Launches a bolt of frostfire at the enemy, causing 92 to 108 Frostfire damage, slowing movement speed by 40% and causing an additional 27 Frostfire damage over 9 sec. This spell will be checked against the lower of the target's Frost and Fire resists and counts as both Frost and Fire damage.",
    ["GetTrainerServiceDescription(94)"] = "1: string Increases Armor by 380 and frost resistance by 9.   If an enemy strikes the caster, they may have their movement slowed by 30% and the time between their attacks increased by 25% for 5 sec.  Only one type of Armor spell can be active on the Mage at any time.  Lasts 30 min.",
    ["GetTrainerServiceDescription(95)"] = "1: string Transforms the enemy into a sheep, forcing it to wander around for up to 40 sec.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.",
    ["GetTrainerServiceDescription(96)"] = "1: string Scorch the enemy for 85 to 101 Fire damage.",
    ["GetTrainerServiceDescription(97)"] = "1: string Amplifies magic used against the targeted party member, increasing damage taken from spells by up to 75 and healing spells by up to 150.  Lasts 10 min.",
    ["GetTrainerServiceDescription(98)"] = "1: string Increases the target's Intellect by 22 for 1 |4hour:hrs;.",
